'use client';

import { useState, useEffect, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Header from '@/components/Header';
import Footer from '@/components/Footer';
import { Search, Printer, AlertCircle } from 'lucide-react';

// Mudiraj Community official emblem, embedded so the card renders/prints
// identically everywhere without depending on an external image file.
// To use the original high-res logo instead, drop it in /public/mudiraj-logo.png
// and replace LOGO_SRC below with "/mudiraj-logo.png".
const LOGO_SRC = "data:image/webp;base64,";

function IdCardContent() {
  const searchParams = useSearchParams();
  const queryId = searchParams.get('id');

  const [searchQuery, setSearchQuery] = useState(queryId || '');
  const [member, setMember] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (queryId) {
      fetchMemberDetails(queryId);
    }
  }, [queryId]);

  const fetchMemberDetails = async (idToSearch) => {
    if (!idToSearch) return;
    setLoading(true);
    setError('');
    setMember(null);

    try {
      const res = await fetch(`/api/public/status?query=${encodeURIComponent(idToSearch)}`);
      const data = await res.json();

      if (res.ok && data.member) {
        if (data.member.status === 'Active' || data.member.membershipId) {
          setMember(data.member);
        } else {
          setError(`Application found, but ID Card is only generated for Active members. Current Status: ${data.member.status}`);
        }
      } else {
        setError('No member found with that Membership ID or Application No.');
      }
    } catch (err) {
      setError('An error occurred while fetching details.');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    fetchMemberDetails(searchQuery);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="page-wrapper">
      <div className="print-hide">
        <Header />
      </div>

      <main className="main-content" style={{ padding: '36px 0' }}>
        <div className="container" style={{ maxWidth: '800px' }}>
          <div className="print-hide" style={{ textAlign: 'center', marginBottom: '32px' }}>
            <h1 style={{ fontSize: '28px', fontWeight: 800, color: '#7a0c14', marginBottom: '8px' }}>
              Digital ID Card Generator
            </h1>
            <p style={{ color: '#64748b' }}>
              Enter your Membership ID (e.g., MUD-00000001) to view and print your official ID Card.
            </p>
          </div>

          <div className="print-hide card" style={{ marginBottom: '40px', maxWidth: '600px', margin: '0 auto 40px auto' }}>
            <form onSubmit={handleSearch} style={{ display: 'flex', gap: '12px' }}>
              <input
                type="text"
                placeholder="Enter Membership ID..."
                className="form-control"
                style={{ flexGrow: 1, padding: '12px 16px', fontSize: '16px' }}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                required
              />
              <button
                type="submit"
                disabled={loading}
                className="btn btn-primary"
                style={{ padding: '12px 24px', display: 'flex', alignItems: 'center', gap: '8px' }}
              >
                <Search size={20} />
                {loading ? 'Searching...' : 'Search'}
              </button>
            </form>
            {error && (
              <div className="alert alert-error" style={{ marginTop: '16px' }}>
                <AlertCircle size={20} style={{ flexShrink: 0, marginTop: '2px' }} />
                <span>{error}</span>
              </div>
            )}
          </div>

          {member && (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
              {/* ============ ID CARD ============ */}
              <div className="id-card-wrapper" style={{ marginBottom: '32px' }}>

                <div style={{
                  width: '360px',
                  padding: '5px',
                  borderRadius: '22px',
                  background: 'linear-gradient(135deg, #a78bfa, #818cf8 45%, #a78bfa 55%, #6366f1)',
                  boxShadow: '0 22px 45px -12px rgba(0,0,0,0.35), 0 8px 16px -4px rgba(0,0,0,0.15)',
                }}>
                  {/* Thin inner frame */}
                  <div style={{
                    borderRadius: '18px',
                    padding: '3px',
                    background: '#4f46e5',
                  }}>
                    {/* Card body */}
                    <div style={{
                      position: 'relative',
                      borderRadius: '16px',
                      backgroundColor: '#fffdf7',
                      display: 'flex',
                      flexDirection: 'column',
                      minHeight: '460px',
                    }}>

                      {/* Faint watermark emblem */}
                      <div style={{
                        position: 'absolute',
                        top: '50%',
                        left: '50%',
                        width: '260px',
                        height: '260px',
                        transform: 'translate(-50%, -50%)',
                        backgroundImage: `url(${LOGO_SRC})`,
                        backgroundSize: 'contain',
                        backgroundRepeat: 'no-repeat',
                        backgroundPosition: 'center',
                        opacity: 0.06,
                        pointerEvents: 'none',
                        zIndex: 0,
                      }} />

                      {/* Header band */}
                      <div style={{
                        position: 'relative',
                        background: 'linear-gradient(135deg, #6366f1, #4338ca 70%)',
                        color: '#fff',
                        padding: '14px 14px 30px 14px',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '10px',
                        zIndex: 1,
                      }}>
                        <img
                          src={LOGO_SRC}
                          alt="Mudiraj Community Emblem"
                          style={{
                            width: '54px',
                            height: '54px',
                            borderRadius: '50%',
                            border: '2px solid #f6d573',
                            boxShadow: '0 2px 6px rgba(0,0,0,0.3)',
                            flexShrink: 0,
                            background: '#fff',
                          }}
                        />
                        <div style={{ lineHeight: 1.15 }}>
                          <div style={{ fontSize: '10px', fontWeight: 700, letterSpacing: '2px', color: '#c7d2fe' }}>
                            ANDHRA PRADESH
                          </div>
                          <div style={{ fontSize: '17px', fontWeight: 800, letterSpacing: '0.4px', textTransform: 'uppercase' }}>
                            Mudiraj Community
                          </div>
                          <div style={{ fontSize: '9px', color: 'rgba(255,255,255,0.85)', letterSpacing: '1px', marginTop: '2px' }}>
                            Reg. No. 86 / 2015
                          </div>
                        </div>

                        {/* scalloped bottom edge */}
                        <svg viewBox="0 0 360 14" preserveAspectRatio="none" style={{ position: 'absolute', bottom: '-1px', left: 0, width: '100%', height: '14px' }}>
                          <path d="M0,0 Q15,14 30,0 T60,0 T90,0 T120,0 T150,0 T180,0 T210,0 T240,0 T270,0 T300,0 T330,0 T360,0 L360,14 L0,14 Z" fill="#fffdf7" />
                        </svg>
                      </div>

                      {/* OFFICIAL MEMBER ribbon */}
                      <div style={{ display: 'flex', justifyContent: 'center', marginTop: '-8px', zIndex: 2, position: 'relative' }}>
                        <span style={{
                          fontSize: '10px',
                          fontWeight: 800,
                          letterSpacing: '1.5px',
                          color: '#ffffff',
                          background: 'linear-gradient(135deg, #818cf8, #4f46e5)',
                          padding: '3px 14px',
                          borderRadius: '999px',
                          boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
                          border: '1px solid #c7d2fe',
                        }}>
                          OFFICIAL MEMBER
                        </span>
                      </div>

                      {/* Photo */}
                      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', marginTop: '10px', zIndex: 1, position: 'relative' }}>
                        <div style={{
                          width: '96px',
                          height: '96px',
                          borderRadius: '50%',
                          padding: '3px',
                          background: 'linear-gradient(135deg, #a78bfa, #4f46e5)',
                          boxShadow: '0 4px 10px rgba(0,0,0,0.18)',
                        }}>
                          <div style={{
                            width: '100%',
                            height: '100%',
                            borderRadius: '50%',
                            overflow: 'hidden',
                            backgroundColor: '#f1f5f9',
                            border: '2px solid #fffdf7',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                          }}>
                            {member.photoUrl ? (
                              <img src={member.photoUrl} alt="Member" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                            ) : (
                              <span style={{ color: '#94a3b8', fontSize: '11px' }}>No Photo</span>
                            )}
                          </div>
                        </div>

                        {/* Membership ID pill */}
                        <div style={{
                          marginTop: '10px',
                          fontSize: '15px',
                          fontWeight: 800,
                          letterSpacing: '1px',
                          color: '#3730a3',
                          fontFamily: 'monospace',
                          background: 'linear-gradient(135deg, #e0e7ff, #c7d2fe)',
                          padding: '4px 16px',
                          borderRadius: '8px',
                          border: '1px solid #818cf8',
                        }}>
                          {member.membershipId}
                        </div>
                      </div>

                      {/* Details */}
                      <div style={{ flexGrow: 1, padding: '14px 22px 4px 22px', display: 'flex', flexDirection: 'column', gap: '8px', zIndex: 1, position: 'relative' }}>
                        <div style={{ textAlign: 'center' }}>
                          <h2 style={{ fontSize: '17px', fontWeight: 800, color: '#312e81', textTransform: 'uppercase', lineHeight: 1.2, margin: 0 }}>
                            {member.fullName}
                          </h2>
                          <p style={{ fontSize: '11.5px', color: '#5b5b5b', fontWeight: 500, margin: '2px 0 0 0' }}>
                            {member.gender}
                          </p>
                        </div>

                        {member.leadershipPositions && member.leadershipPositions.length > 0 ? (
                          <div style={{ textAlign: 'center' }}>
                            <span style={{
                              backgroundColor: '#e0e7ff',
                              color: '#3730a3',
                              fontSize: '10px',
                              fontWeight: 700,
                              padding: '3px 10px',
                              borderRadius: '4px',
                              border: '1px solid #c7d2fe',
                              textTransform: 'uppercase',
                            }}>
                              {member.leadershipPositions[0].positionTitle}
                            </span>
                          </div>
                        ) : null}

                        <div style={{
                          display: 'grid',
                          gridTemplateColumns: '1fr 1fr',
                          rowGap: '9px',
                          columnGap: '8px',
                          fontSize: '11.5px',
                          borderTop: '1px dashed #818cf8',
                          paddingTop: '10px',
                          marginTop: '2px',
                        }}>
                          <div>
                            <span style={{ display: 'block', fontSize: '9px', color: '#9a9a9a', textTransform: 'uppercase', fontWeight: 700, letterSpacing: '0.5px' }}>Mobile</span>
                            <span style={{ fontWeight: 700, color: '#2b2b2b' }}>{member.mobile ? `+91 ${member.mobile}` : '—'}</span>
                          </div>
                          <div>
                            <span style={{ display: 'block', fontSize: '9px', color: '#9a9a9a', textTransform: 'uppercase', fontWeight: 700, letterSpacing: '0.5px' }}>Blood Group</span>
                            <span style={{ fontWeight: 800, color: '#4f46e5' }}>{member.bloodGroup || '—'}</span>
                          </div>
                          <div style={{ gridColumn: 'span 2' }}>
                            <span style={{ display: 'block', fontSize: '9px', color: '#9a9a9a', textTransform: 'uppercase', fontWeight: 700, letterSpacing: '0.5px' }}>Address</span>
                            <span style={{ fontWeight: 700, color: '#2b2b2b', lineHeight: 1.3, display: 'block' }}>
                              {member.street || ''}
                              {member.street && member.pincode ? <br /> : null}
                              {member.pincode ? `Pincode: ${member.pincode}` : ''}
                            </span>
                          </div>
                        </div>
                      </div>

                      {/* Footer strip */}
                      <div style={{
                        marginTop: '10px',
                        borderTop: '2px solid #818cf8',
                        background: 'linear-gradient(135deg, #e0e7ff, #c7d2fe)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        padding: '10px 16px',
                        zIndex: 1,
                        position: 'relative',
                      }}>
                        <div style={{ fontSize: '8px', color: '#4338ca', textTransform: 'uppercase', fontWeight: 700, lineHeight: 1.35, maxWidth: '190px', letterSpacing: '0.2px' }}>
                          Property of AP Mudiraj Community. If found, please return to the nearest organization office.
                        </div>
                        <img
                          src={`https://api.qrserver.com/v1/create-qr-code/?size=54x54&data=Verify:${member.membershipId}`}
                          alt="QR Code"
                          style={{ width: '48px', height: '48px', borderRadius: '4px', border: '1px solid #818cf8', background: '#fff', padding: '2px' }}
                        />
                      </div>

                      {/* thin tricolor-style accent bar at the very bottom for a finished look */}
                      <div style={{ height: '6px', background: 'linear-gradient(90deg, #4f46e5, #a78bfa, #4f46e5)' }} />
                    </div>
                  </div>
                </div>
              </div>

              <div className="print-hide">
                <button
                  onClick={handlePrint}
                  className="btn btn-primary"
                  style={{ padding: '12px 32px', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '16px', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)' }}
                >
                  <Printer size={20} />
                  Print ID Card
                </button>
                <p style={{ fontSize: '12px', color: '#64748b', textAlign: 'center', marginTop: '12px' }}>
                  For best results, print on A4 paper with background graphics enabled.
                </p>
              </div>
            </div>
          )}
        </div>
      </main>

      <div className="print-hide">
        <Footer />
      </div>

      <style dangerouslySetInnerHTML={{
        __html: `
        @media print {
          * {
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
            color-adjust: exact !important;
          }
          body {
            background-color: white !important;
            margin: 0;
            padding: 0;
          }
          .print-hide {
            display: none !important;
          }
          .id-card-wrapper {
            margin: 0 !important;
            padding: 0 !important;
            box-shadow: none !important;
            page-break-inside: avoid;
            transform: scale(1.0);
            transform-origin: top left;
          }
          @page {
            margin: 0.5cm;
          }
        }
      `}} />
    </div>
  );
}

export default function IdCardPage() {
  return (
    <Suspense fallback={<div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading...</div>}>
      <IdCardContent />
    </Suspense>
  );
}